// Prepare data for AI analysis
const webhookData = $input.first().json;
const batchData = $input.last().json;

let contacts = [];
let source = 'unknown';

// Determine data source and prepare contact data
if (webhookData && webhookData.properties && webhookData.properties.hs_object_id) {
  // Webhook triggered
  source = 'webhook';
  const engagementData = batchData;

  let contact;
  if (webhookData.id) {
    contact = webhookData;
  } else {
    contact = webhookData.results ? webhookData.results[0] : webhookData;
  }

  const props = contact.properties || {};

  contacts.push({
    contactId: contact.id,
    email: props.email,
    name: `${props.firstname || ''} ${props.lastname || ''}`.trim(),
    company: props.company,
    jobTitle: props.jobtitle,
    pageViews: parseInt(props.hs_analytics_num_page_views) || 0,
    visits: parseInt(props.hs_analytics_num_visits) || 0,
    lastUrl: props.hs_analytics_last_url || '',
    lastActivity: props.lastmodifieddate,
    lifecycleStage: props.hs_lifecyclestage,
    engagements: engagementData && engagementData.results ? engagementData.results : [],
    source: 'webhook'
  });

} else if (batchData && batchData.results) {
  // Batch processing
  source = 'batch';

  for (const contact of batchData.results) {
    const props = contact.properties || {};

    // Skip if already scored recently (unless score is low)
    const currentScore = parseInt(props.lead_score) || 0;
    if (currentScore >= 80) {
      continue; // Skip high-scoring contacts
    }

    contacts.push({
      contactId: contact.id,
      email: props.email,
      name: `${props.firstname || ''} ${props.lastname || ''}`.trim(),
      company: props.company,
      jobTitle: props.jobtitle,
      currentScore: currentScore,
      pageViews: parseInt(props.hs_analytics_num_page_views) || 0,
      visits: parseInt(props.hs_analytics_num_visits) || 0,
      lastUrl: props.hs_analytics_last_url || '',
      lastActivity: props.lastmodifieddate,
      lifecycleStage: props.hs_lifecyclestage,
      daysSinceActivity: Math.floor((new Date() - new Date(props.lastmodifieddate)) / (1000 * 60 * 60 * 24)),
      source: 'batch'
    });
  }
}

console.log(`Prepared ${contacts.length} contacts for AI analysis from ${source} source`);
return contacts;

