// Company Research Tool
// Simulate company research using available data and patterns
const companyName = $input.first().json.companyName;
const industry = $input.first().json.industry || '';

// Simulate company research results
const companyPatterns = {
  // Tech company patterns
  'tech': {
    avgSize: '50-200',
    growthStage: 'Growing',
    funding: 'Seed/Series A',
    marketPosition: 'Emerging'
  },
  // Enterprise patterns
  'enterprise': {
    avgSize: '1000+',
    growthStage: 'Mature',
    funding: 'Public/Private Equity',
    marketPosition: 'Established'
  },
  // Startup patterns
  'startup': {
    avgSize: '1-50',
    growthStage: 'Early',
    funding: 'Pre-Seed/Angel',
    marketPosition: 'Disruptive'
  }
};

// Determine company type based on name and patterns
let companyType = 'unknown';
if (companyName.toLowerCase().includes('tech') || companyName.toLowerCase().includes('software') || companyName.toLowerCase().includes('solutions')) {
  companyType = 'tech';
} else if (companyName.toLowerCase().includes('corp') || companyName.toLowerCase().includes('inc') || companyName.toLowerCase().includes('llc')) {
  companyType = 'enterprise';
} else if (companyName.toLowerCase().includes('labs') || companyName.toLowerCase().includes('startup')) {
  companyType = 'startup';
}

const research = companyPatterns[companyType] || companyPatterns.unknown;

return {
  companyName: companyName,
  industry: industry || 'Technology',
  estimatedSize: research.avgSize,
  growthStage: research.growthStage,
  fundingStage: research.funding,
  marketPosition: research.marketPosition,
  confidence: 75,
  dataPoints: ['Name pattern analysis', 'Industry classification', 'Size estimation'],
  researchTimestamp: new Date().toISOString()
};

// Job Title Analyzer Tool
// Analyze job title for seniority and decision-making power
const jobTitle = $input.first().json.jobTitle;
const company = $input.first().json.company || '';

// Seniority levels and scores
const seniorityLevels = {
  'c-level': {
    titles: ['ceo', 'cto', 'cfo', 'cio', 'coo', 'cmo', 'cpo', 'chro', 'chief', 'president'],
    score: 100,
    decisionPower: 'Final',
    budgetAuthority: 'Unlimited'
  },
  'vp-level': {
    titles: ['vice president', 'vp', 'director'],
    score: 85,
    decisionPower: 'High',
    budgetAuthority: 'High ($100K+)'
  },
  'manager-level': {
    titles: ['manager', 'head', 'lead', 'principal', 'supervisor'],
    score: 70,
    decisionPower: 'Medium',
    budgetAuthority: 'Medium ($10K-$100K)'
  },
  'senior-level': {
    titles: ['senior', 'sr.', 'principal', 'specialist'],
    score: 55,
    decisionPower: 'Low-Medium',
    budgetAuthority: 'Low ($1K-$10K)'
  },
  'individual-contributor': {
    titles: ['analyst', 'associate', 'coordinator', 'assistant', 'junior', 'intern'],
    score: 30,
    decisionPower: 'Low',
    budgetAuthority: 'Minimal (<$1K)'
  }
};

// Analyze job title
const titleLower = jobTitle.toLowerCase();
let detectedLevel = 'individual-contributor';
let score = 30;
let decisionPower = 'Low';
let budgetAuthority = 'Minimal (<$1K)';

for (const [level, data] of Object.entries(seniorityLevels)) {
  for (const titleKeyword of data.titles) {
    if (titleLower.includes(titleKeyword)) {
      detectedLevel = level;
      score = data.score;
      decisionPower = data.decisionPower;
      budgetAuthority = data.budgetAuthority;
      break;
    }
  }
  if (detectedLevel !== 'individual-contributor') break;
}

// Additional factors
const hasInfluence = titleLower.includes('manager') || titleLower.includes('lead') || titleLower.includes('head');
const isTechnical = titleLower.includes('engineer') || titleLower.includes('developer') || titleLower.includes('architect');
const isBusiness = titleLower.includes('business') || titleLower.includes('sales') || titleLower.includes('marketing');

return {
  jobTitle: jobTitle,
  company: company,
  detectedLevel: detectedLevel,
  seniorityScore: score,
  decisionPower: decisionPower,
  budgetAuthority: budgetAuthority,
  hasInfluence: hasInfluence,
  isTechnical: isTechnical,
  isBusiness: isBusiness,
  confidence: 85,
  analysis: `Detected ${detectedLevel.replace('-', ' ')} with ${decisionPower} decision-making power`,
  analysisTimestamp: new Date().toISOString()
};

// Behavioral Pattern Detector Tool
// Detect buying signals from digital behavior patterns
const pageViews = $input.first().json.pageViews;
const visits = $input.first().json.visits;
const lastUrl = $input.first().json.lastUrl || '';
const urlHistory = $input.first().json.urlHistory || [];

// Behavioral patterns and indicators
const patterns = {
  highIntentUrls: ['pricing', 'demo', 'trial', 'contact', 'enterprise', 'quote', 'proposal'],
  researchUrls: ['about', 'features', 'solutions', 'services', 'case-study', 'testimonial'],
  productUrls: ['product', 'platform', 'tool', 'software'],
  supportUrls: ['help', 'support', 'documentation', 'faq']
};

// Analyze URL patterns
let detectedPatterns = [];
let intentSignals = [];
let lastUrlCategory = 'other';

for (const [category, keywords] of Object.entries(patterns)) {
  for (const keyword of keywords) {
    if (lastUrl.toLowerCase().includes(keyword)) {
      lastUrlCategory = category;
      detectedPatterns.push(`${category}: ${keyword}`);
      break;
    }
  }
}

// Calculate behavioral scores
const engagementRate = visits > 0 ? pageViews / visits : 0;
const visitFrequency = visits; // Higher is better
const depthScore = pageViews > 20 ? 100 : pageViews > 10 ? 75 : pageViews > 5 ? 50 : 25;
const frequencyScore = visits > 10 ? 100 : visits > 5 ? 75 : visits > 2 ? 50 : 25;

// Detect buying signals
if (lastUrlCategory === 'highIntentUrls') {
  intentSignals.push('High-intent page visit (pricing/demo)');
}
if (engagementRate > 3) {
  intentSignals.push('High engagement rate (deep browsing)');
}
if (visits > 5) {
  intentSignals.push('Multiple return visits');
}
if (pageViews > 15) {
  intentSignals.push('Extensive research behavior');
}

// Calculate overall behavioral score
const behavioralScore = (depthScore * 0.6) + (frequencyScore * 0.4);

return {
  pageViews: pageViews,
  visits: visits,
  lastUrl: lastUrl,
  lastUrlCategory: lastUrlCategory,
  engagementRate: Math.round(engagementRate * 100) / 100,
  depthScore: depthScore,
  frequencyScore: frequencyScore,
  behavioralScore: Math.round(behavioralScore),
  detectedPatterns: detectedPatterns,
  intentSignals: intentSignals,
  buyingSignals: intentSignals.length,
  confidence: 80,
  analysis: `Behavioral score ${behavioralScore}/100 with ${intentSignals.length} buying signals`,
  analysisTimestamp: new Date().toISOString()
};

// Engagement Quality Scorer Tool
// Evaluate quality and significance of engagement activities
const engagements = $input.first().json.engagements || [];
const currentScore = $input.first().json.engagementScore || 0;

// Engagement type weights
const engagementWeights = {
  'MEETING': { weight: 100, quality: 'High' },
  'CALL': { weight: 80, quality: 'High' },
  'EMAIL': { weight: 60, quality: 'Medium' },
  'NOTE': { weight: 40, quality: 'Medium' },
  'TASK': { weight: 70, quality: 'Medium-High' },
  'FORM_SUBMISSION': { weight: 90, quality: 'High' }
};

// Analyze engagements
let totalScore = 0;
let qualityBreakdown = [];
let engagementTypes = [];

for (const engagement of engagements) {
  const type = engagement.type || 'UNKNOWN';
  const weight = engagementWeights[type] || { weight: 20, quality: 'Low' };

  totalScore += weight.weight;
  qualityBreakdown.push(`${type}: ${weight.quality}`);
  engagementTypes.push(type);

  // Check for high-value interactions
  if (type === 'MEETING' && engagement.duration > 1800) { // 30+ minutes
    totalScore += 20; // Bonus for long meetings
  }
  if (type === 'CALL' && engagement.duration > 600) { // 10+ minutes
    totalScore += 15; // Bonus for substantial calls
  }
}

// Calculate quality metrics
const avgEngagementQuality = totalScore > 0 ? totalScore / engagements.length : 0;
const engagementFrequency = engagements.length;
const hasHighValueEngagement = engagementTypes.some(type => ['MEETING', 'CALL', 'FORM_SUBMISSION'].includes(type));

// Determine engagement level
let engagementLevel = 'Low';
if (avgEngagementQuality >= 80 || hasHighValueEngagement) {
  engagementLevel = 'High';
} else if (avgEngagementQuality >= 60) {
  engagementLevel = 'Medium';
}

return {
  engagementCount: engagements.length,
  engagementTypes: engagementTypes,
  totalEngagementScore: totalScore,
  avgEngagementQuality: Math.round(avgEngagementQuality),
  engagementLevel: engagementLevel,
  hasHighValueEngagement: hasHighValueEngagement,
  qualityBreakdown: qualityBreakdown,
  confidence: 85,
  analysis: `${engagementLevel} engagement quality with ${engagements.length} interactions`,
  analysisTimestamp: new Date().toISOString()
};

// Temporal Analysis Tool
// Analyze timing patterns, recency, and urgency indicators
const daysSinceActivity = $input.first().json.daysSinceActivity;
const lastActivity = $input.first().json.lastActivity || '';
const activityPattern = $input.first().json.activityPattern || [];

// Time-based scoring factors
const timeFactors = {
  urgency: {
    veryHigh: { days: 1, score: 100, label: 'Immediate' },
    high: { days: 3, score: 90, label: 'Urgent' },
    medium: { days: 7, score: 75, label: 'Active' },
    low: { days: 14, score: 50, label: 'Warm' },
    veryLow: { days: 30, score: 25, label: 'Cold' },
    stale: { days: 60, score: 10, label: 'Stale' }
  }
};

// Determine urgency level
let urgencyLevel = 'low';
let timeScore = 25;
let urgencyLabel = 'Cold';

for (const [level, data] of Object.entries(timeFactors)) {
  if (daysSinceActivity <= data.days) {
    urgencyLevel = level;
    timeScore = data.score;
    urgencyLabel = data.label;
    break;
  }
}

// Analyze activity patterns if available
let patternAnalysis = 'No pattern data';
if (activityPattern.length > 0) {
  const recentActivity = activityPattern.slice(-7).reduce((sum, val) => sum + val, 0);
  const avgRecentActivity = recentActivity / Math.min(7, activityPattern.length);

  if (avgRecentActivity > 5) {
    patternAnalysis = 'High recent activity pattern';
    timeScore += 15;
  } else if (avgRecentActivity > 2) {
    patternAnalysis = 'Moderate recent activity pattern';
    timeScore += 5;
  }
}

// Calculate recency bonus/penalty
let recencyAdjustment = 0;
if (daysSinceActivity <= 3) {
  recencyAdjustment = 20; // Bonus for very recent activity
} else if (daysSinceActivity >= 45) {
  recencyAdjustment = -15; // Penalty for stale activity
}

const finalTimeScore = Math.max(0, Math.min(100, timeScore + recencyAdjustment));

return {
  daysSinceActivity: daysSinceActivity,
  lastActivity: lastActivity,
  urgencyLevel: urgencyLevel,
  urgencyLabel: urgencyLabel,
  timeScore: finalTimeScore,
  recencyAdjustment: recencyAdjustment,
  patternAnalysis: patternAnalysis,
  isVeryRecent: daysSinceActivity <= 3,
  isStale: daysSinceActivity >= 45,
  confidence: 90,
  analysis: `${urgencyLabel} timing with ${finalTimeScore}/100 time score`,
  analysisTimestamp: new Date().toISOString()
};

// Competitive Intelligence Tool
// Research competitive landscape and market positioning
const company = $input.first().json.company;
const industry = $input.first().json.industry || 'Technology';

// Simulate competitive intelligence based on industry patterns
const competitiveData = {
  'Technology': {
    avgCompetitors: 15,
    marketSaturation: 'High',
    growthRate: '15-25%',
    barriers: 'High innovation requirements',
    opportunities: 'AI integration, sustainability focus'
  },
  'Healthcare': {
    avgCompetitors: 8,
    marketSaturation: 'Medium',
    growthRate: '8-12%',
    barriers: 'Regulatory compliance',
    opportunities: 'Telemedicine, aging population'
  },
  'Finance': {
    avgCompetitors: 12,
    marketSaturation: 'High',
    growthRate: '5-10%',
    barriers: 'Trust and regulation',
    opportunities: 'Digital transformation, ESG'
  },
  'Manufacturing': {
    avgCompetitors: 10,
    marketSaturation: 'Medium',
    growthRate: '3-8%',
    barriers: 'Supply chain complexity',
    opportunities: 'IoT, automation'
  }
};

const industryData = competitiveData[industry] || competitiveData.Technology;

// Analyze company positioning
let positioningScore = 50; // Default neutral
let positioning = 'Mid-market';

// Simulate positioning analysis based on company characteristics
if (company.toLowerCase().includes('global') || company.toLowerCase().includes('international')) {
  positioningScore = 75;
  positioning = 'Global player';
} else if (company.toLowerCase().includes('local') || company.toLowerCase().includes('regional')) {
  positioningScore = 35;
  positioning = 'Local focus';
} else if (company.toLowerCase().includes('enterprise') || company.toLowerCase().includes('corp')) {
  positioningScore = 65;
  positioning = 'Enterprise focus';
}

// Calculate competitive advantage
const competitiveAdvantage = Math.max(0, positioningScore - 40);
const marketDifficulty = industryData.marketSaturation === 'High' ? 80 : industryData.marketSaturation === 'Medium' ? 60 : 40;

return {
  company: company,
  industry: industry,
  avgCompetitors: industryData.avgCompetitors,
  marketSaturation: industryData.marketSaturation,
  growthRate: industryData.growthRate,
  barriers: industryData.barriers,
  opportunities: industryData.opportunities,
  positioningScore: positioningScore,
  positioning: positioning,
  competitiveAdvantage: competitiveAdvantage,
  marketDifficulty: marketDifficulty,
  confidence: 70,
  analysis: `${positioning} positioning in ${industryData.marketSaturation.toLowerCase()} market`,
  analysisTimestamp: new Date().toISOString()
};

// Process enhanced AI response with tools data
const aiResponse = $input.first().json;
const contactData = $input.last().json;

try {
  // Parse AI response
  let aiAnalysis;
  if (typeof aiResponse.output === 'string') {
    aiAnalysis = JSON.parse(aiResponse.output);
  } else {
    aiAnalysis = aiResponse.output || aiResponse;
  }

  // Ensure we have valid analysis
  if (!aiAnalysis || typeof aiAnalysis !== 'object') {
    throw new Error('Invalid AI response format');
  }

  // Extract tool usage information
  const toolsUsed = [];
  if (aiAnalysis.companyResearch) toolsUsed.push('Company Research');
  if (aiAnalysis.jobAnalysis) toolsUsed.push('Job Title Analysis');
