    reasoning: 'AI analysis failed, used advanced behavioral scoring with heuristics',
    recommendedAction: 'Review manually and consider technical issues',
    nextSteps: ['Verify AI service status', 'Manual review recommended'],
    riskFactors: ['AI analysis unavailable', 'Potential scoring inaccuracy'],
    toolsUsed: [],
    currentScore: contactData.currentScore || 0,
    newScore: fallbackScore,
    scoreChange: fallbackScore - (contactData.currentScore || 0),
    pageViews: contactData.pageViews,
    visits: contactData.visits,
    lastUrl: contactData.lastUrl,
    lastActivity: contactData.lastActivity,
    lifecycleStage: contactData.lifecycleStage,
    daysSinceActivity: contactData.daysSinceActivity,
    timestamp: new Date().toISOString(),
    source: contactData.source,
    aiProcessed: false,
    analysisDepth: 'fallback',
