          <p><strong>Company:</strong> ${lead.company}</p>
          <p><strong>Title:</strong> ${lead.jobTitle}</p>
          <p><strong>Score Change:</strong> <span style="color: ${lead.scoreChange > 0 ? '#4caf50' : '#f44336'};">${lead.scoreChange > 0 ? '+' : ''}${lead.scoreChange} pts</span></p>
        </div>
      </div>

      ${toolsSection}

      <h3>🧠 AI Reasoning:</h3>
      <div style="background-color: #e8f5e8; border-left: 4px solid #4caf50; padding: 15px; margin: 10px 0;">
        <p><strong>Analysis:</strong> ${lead.reasoning}</p>
      </div>

      <h3>🚀 Buying Signals Detected:</h3>
      <div style="background-color: #fff3e0; padding: 15px; border-radius: 8px;">
        ${lead.signals.map(signal => `<span style="background-color: #ff9800; color: white; padding: 3px 8px; border-radius: 15px; margin: 3px; display: inline-block;">✅ ${signal}</span>`).join(' ')}
      </div>

      ${riskSection}
      ${nextStepsSection}

      <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 20px; border-radius: 8px; margin: 20px 0;">
        <h3 style="margin: 0 0 10px 0;">🤖 AI Strategic Recommendation:</h3>
        <p style="margin: 0; font-size: 16px;"><strong>${lead.recommendedAction}</strong></p>
      </div>

      <p><em>This enhanced AI analysis was generated on ${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}</em></p>
    `,
    type: 'individual'
  };
} else {
  // Batch notification (schedule trigger)
  const leadsList = leads.map(lead => {
    const data = lead.json;
    const aiBadge = data.aiProcessed ? '🤖' : '📊';
    const scoreColor = data.score >= 80 ? '#4caf50' : data.score >= 50 ? '#ff9800' : '#f44336';
    const confidenceColor = data.confidence >= 80 ? '#4caf50' : data.confidence >= 60 ? '#ff9800' : '#f44336';
    const toolsCount = data.toolsUsed ? data.toolsUsed.length : 0;

    return `
      <tr>
        <td>${aiBadge} ${data.name}</td>
        <td>${data.email}</td>
        <td>${data.company}</td>
        <td>${data.jobTitle}</td>
        <td><strong style="color: ${scoreColor}; font-size: 14px;">${data.newScore || data.score}</strong></td>
        <td><span style="background-color: ${data.intentLevel === 'high' ? '#ff6b6b' : data.intentLevel === 'medium' ? '#ffa726' : '#66bb6a'}; color: white; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${data.intentLevel.toUpperCase()}</span></td>
        <td><span style="color: ${confidenceColor}; font-weight: bold;">${data.confidence}%</span></td>
        <td><span style="background-color: ${data.priority === 'immediate' ? '#d32f2f' : data.priority === 'high' ? '#f57c00' : '#388e3c'}; color: white; padding: 2px 4px; border-radius: 2px; font-size: 10px;">${data.priority.toUpperCase()}</span></td>
        <td>${toolsCount} tools</td>
        <td>${data.signals.slice(0, 2).join(', ')}${data.signals.length > 2 ? '...' : ''}</td>
        <td>${data.scoreChange > 0 ? '+' : ''}${data.scoreChange}</td>
      </tr>`;
  }).join('');

  const aiProcessedCount = leads.filter(lead => lead.json.aiProcessed).length;
  const comprehensiveAnalysisCount = leads.filter(lead => lead.json.analysisDepth === 'comprehensive').length;
  const totalToolsUsed = leads.reduce((sum, lead) => sum + (lead.json.toolsUsed ? lead.json.toolsUsed.length : 0), 0);

  return {
    subject: `🤖 Enhanced AI Batch Alert: ${leads.length} High-Intent Leads Analyzed`,
    htmlContent: `
      <h2>🤖 Advanced AI Lead Analysis Report</h2>
      <p><strong>${leads.length}</strong> high-intent leads identified with enhanced AI analysis (${aiProcessedCount} AI-processed, ${comprehensiveAnalysisCount} comprehensive analysis).</p>

      <div style="background-color: #f8f9fa; padding: 15px; border-radius: 8px; margin: 20px 0;">
        <h3>📊 Analysis Summary:</h3>
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px;">
          <div><strong>Total Leads:</strong> ${leads.length}</div>
          <div><strong>AI Processed:</strong> ${aiProcessedCount}</div>
          <div><strong>Comprehensive:</strong> ${comprehensiveAnalysisCount}</div>
          <div><strong>Tools Used:</strong> ${totalToolsUsed}</div>
        </div>
      </div>

      <h3>📋 Lead Details</h3>
      <table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 100%; font-size: 12px;">
        <thead>
          <tr style="background-color: #f2f2f2;">
            <th>Name</th>
            <th>Email</th>
            <th>Company</th>
            <th>Title</th>
            <th>Score</th>
            <th>Intent</th>
            <th>Confidence</th>
            <th>Priority</th>
            <th>Tools</th>
            <th>Top Signals</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          ${leadsList}
        </tbody>
      </table>

      <h3>🧠 Top AI Insights</h3>
      <div style="background-color: #e3f2fd; padding: 15px; border-radius: 8px; margin: 20px 0;">
        ${leads.slice(0, 3).map(lead => {
          const data = lead.json;
          return `<div style="margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid #bbdefb;"><strong>${data.name}:</strong> ${data.reasoning || 'Standard analysis applied'}</div>`;
        }).join('')}
        ${leads.length > 3 ? `<div><em>...and ${leads.length - 3} more leads with detailed AI analysis</em></div>` : ''}
      </div>

      <h3>🚀 Strategic Recommendations</h3>
      <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 20px; border-radius: 8px; margin: 20px 0;">
        <ul style="margin: 0; padding-left: 20px;">
          <li><strong>🎯 Priority Sequencing:</strong> Focus on immediate priority leads with 80+ scores</li>
          <li><strong>🛠️ Tool-Driven Approach:</strong> Leverage AI insights from specialized analysis tools</li>
          <li><strong>🧠 Reasoning-Based Outreach:</strong> Reference specific AI reasoning in communications</li>
          <li><strong>⚠️ Risk Mitigation:</strong> Address identified risk factors proactively</li>
          <li><strong>📋 Step-by-Step:</strong> Follow AI-recommended next steps systematically</li>
        </ul>
      </div>

      <p><em>This enhanced AI report was generated on ${new Date().toLocaleDateString()} at ${new Date().toLocaleTimeString()}</em></p>
    `,
    type: 'batch'
  };
}
